import React from 'react';
import { useState, useEffect } from 'react';
import StylizedBoardDisplay from "./BoardDisplay";
import ControlsDisplay from './Controls';
import Board from './game';
import useKeyPress from './useKeyPress';

const width = 10;
const height = 24; // top 4 rows are hidden (buffer); visible playable rows = 20
const gameBoard = new Board(width, height);

function App() {
    const [game_board, setBoard] = useState(() => gameBoard.renderGrid());
    // Repeat tuning: snappier horizontal, standard soft drop, instant rotate
    const DAS_A_MS = 150;  // horizontal delayed auto shift (before repeat starts)
    const ARR_A_MS = 50;  // horizontal auto repeat rate (gap between presses)
    const DAS_S_MS = 140; // soft drop delayed auto shift
    const ARR_S_MS = 35;  // soft drop auto repeat rate
    const DAS_W_MS = 250;  // rotation delayed auto shift (before repeat starts)
    const ARR_W_MS = 250;  // rotation repeat rate (match A/D gap)
    const repeatTimersRef = React.useRef({}); // key -> timeout id
    
    useEffect(() => {
        const id = setInterval(() => {
            setBoard(gameBoard.renderGrid());
        }, 50);
        return () => clearInterval(id);
    }, []);

    // Handle keyboard input and delegate to gameBoard methods
    useKeyPress((key, meta) => {
        const k = (key || '').toLowerCase();
        const type = (meta && meta.type) || 'down';
        // no need to track last-held; we allow concurrent repeats per key

        const stopRepeat = (kk) => {
            const timers = repeatTimersRef.current;
            if (timers[kk]) {
                clearTimeout(timers[kk]);
                delete timers[kk];
            }
        };

        const step = (kk) => {
            if (kk === 'a') gameBoard.moveLeft();
            else if (kk === 'd') gameBoard.moveRight();
            else if (kk === 's') gameBoard.softDrop();
            else if (kk === 'w') gameBoard.rotateCW();
            setBoard(gameBoard.renderGrid());
        };

        const scheduleRepeat = (kk, delay, arr) => {
            const timers = repeatTimersRef.current;
            if (timers[kk]) return; // already repeating
            timers[kk] = setTimeout(function tick() {
                // Execute step then schedule next if still repeating
                step(kk);
                if (timers[kk]) {
                    timers[kk] = setTimeout(tick, arr);
                }
            }, delay);
        };

        try {
            if (k === 'f') {
                if (type === 'down') {
                    if (gameBoard.timer) gameBoard.stopGravity(); else gameBoard.startGravity();
                }
                // do not alter repeats for movement/rotation
            } else if (k === 'w') {
                if (type === 'down') {
                    step('w');
                    // Apply delay before rotation starts repeating
                    scheduleRepeat('w', DAS_W_MS, ARR_W_MS);
                } else if (type === 'up') {
                    stopRepeat('w');
                } else if (type === 'repeat') {
                    // Ignore OS repeat for rotation; timer drives smooth ARR
                }
            } else if (k === 'e') {
                if (type === 'down') gameBoard.holdSwap();
                // no repeat for hold
            } else if (k === ' ') {
                if (type === 'down') gameBoard.hardDrop();
                // no repeat for hard drop
            } else if (k === 'a' || k === 'd' || k === 's') {
                if (type === 'down') {
                    step(k);
                    if (k === 's') scheduleRepeat('s', DAS_S_MS, ARR_S_MS);
                    else scheduleRepeat(k, DAS_A_MS, ARR_A_MS);
                } else if (type === 'repeat') {
                    // We rely on our timer for consistent ARR; ignore OS repeat here
                    // no-op
                } else if (type === 'up') {
                    stopRepeat(k);
                }
            }
        } catch (e) {
            console.error(e);
        } finally {
            setBoard(gameBoard.renderGrid());
        }
    });

    return (
        <div className="TetrisGame">
            <ControlsDisplay inputboard={gameBoard} initialShowInfo={true} />
            <StylizedBoardDisplay inputboard={game_board} inputheight={height} inputwidth={width} paused={!gameBoard.timer} />
        </div>
    );
}

export default App;