import { useState, useEffect, useRef } from 'react';

//THIS CODE WAS TAKEN FROM https://betterprogramming.pub/create-a-typing-game-with-react-hooks-usekeypress-and-faker-28bbc7919820
//I DID NOT WRITE IT


const useKeyPress = (callback) => {
  const [keyPressed, setKeyPressed] = useState();
  const pressedRef = useRef(new Set());
  const orderRef = useRef([]); // order of keydowns
  const lastKeyRef = useRef(null);

  useEffect(() => {
    const isAllowed = (key) => (key.length === 1 || key === ' ');

    const meta = () => ({
      lastKey: lastKeyRef.current,
      held: new Set(pressedRef.current),
    });

    const downHandler = (ev) => {
      const key = ev.key;
      if (!isAllowed(key)) return;

      const pressed = pressedRef.current;
      const order = orderRef.current;

      if (!ev.repeat) {
        if (!pressed.has(key)) {
          pressed.add(key);
          order.push(key);
        }
        lastKeyRef.current = key;
        setKeyPressed(key);
        if (callback) callback(key, { type: 'down', ...meta() });
      } else {
        if (lastKeyRef.current === key) {
          setKeyPressed(key);
          if (callback) callback(key, { type: 'repeat', ...meta() });
        }
      }
    };

    const upHandler = (ev) => {
      const key = ev.key;
      if (!isAllowed(key)) return;
      const pressed = pressedRef.current;
      const order = orderRef.current;
      pressed.delete(key);
      for (let i = order.length - 1; i >= 0; i--) {
        if (order[i] === key) order.splice(i, 1);
      }
      lastKeyRef.current = order[order.length - 1] || null;
      setKeyPressed(null);
      if (callback) callback(key, { type: 'up', ...meta() });
    };

    window.addEventListener('keydown', downHandler);
    window.addEventListener('keyup', upHandler);
    return () => {
      window.removeEventListener('keydown', downHandler);
      window.removeEventListener('keyup', upHandler);
    };
  }, [callback]);

  return keyPressed;
};

export default useKeyPress;