import React, { useState } from 'react';
import PiecePreview from './PiecePreview';

export default function ControlsDisplay(props) {
    const gameBoard = props.inputboard;
    const [showInfo, setShowInfo] = useState(!!props.initialShowInfo);
    const state = gameBoard.getState ? gameBoard.getState() : null;
    const nextList = (state && Array.isArray(state.next))
        ? state.next
        : (Array.isArray(gameBoard.next) ? gameBoard.next : []);

    return (
        <div className="TetrisControls">
            <div className="stats">
                <div className='score-display'>Score: {state ? Math.floor(state.score) : gameBoard.score}</div>
                <div className='level-display'>Level: {state ? state.level : gameBoard.level}</div>
                <div className='highscore-display'>High score: {state ? Math.floor(state.highscore) : gameBoard.highscore}</div>
            </div>

            <div className="controls-row">
                <button className="btn primary" onClick={() => gameBoard.startGravity()}>Start</button>
                <button className="btn" onClick={() => gameBoard.timer ? gameBoard.stopGravity() : gameBoard.startGravity()}>{gameBoard.timer ? 'Pause' : 'Resume'}</button>
                <button className="btn" onClick={() => { gameBoard.stopGravity(); gameBoard.reset(); gameBoard.startGravity(); }}>Restart</button>
                <button className="btn ghost" onClick={() => setShowInfo(true)}>Controls</button>
            </div>

                    <div className="hold-next">
                        <div className="next-block">
                            <div className="label">Next</div>
                            <div className="next-list">
                                {nextList.map((p, i) => (
                                    <PiecePreview key={i} piece={p} />
                                ))}
                            </div>
                        </div>
                        <div className="hold-block">
                            <div className="label">Hold</div>
                            <PiecePreview piece={state ? state.hold : gameBoard.hold} />
                        </div>
                    </div>

            {showInfo && (
                <div className="info-modal" role="dialog" aria-modal="true" onClick={() => setShowInfo(false)}>
                    <div className="info-content" onClick={(e) => e.stopPropagation()}>
                        <div className="info-header">
                            <h3>How to play</h3>
                            <button className="icon" aria-label="Close" onClick={() => setShowInfo(false)}>×</button>
                        </div>
                        <ul>
                            <li><kbd>A</kbd> / <kbd>D</kbd> — Move left/right</li>
                            <li><kbd>W</kbd> — Rotate</li>
                            <li><kbd>S</kbd> — Soft drop</li>
                            <li><kbd>Space</kbd> — Hard drop</li>
                            <li><kbd>E</kbd> — Swap HOLD piece</li>
                            <li><kbd>F</kbd> — Pause/Play</li>
                        </ul>
                        <div className="tip">Pieces auto-drop periodically; speed increases with level.</div>
                    </div>
                </div>
            )}
        </div>
    );
}

